<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {ArrowUp,ArrowDown,Plus,X} from 'lucide-vue-next';
import {useStudio} from '../stores/studio';
import type {Generation} from '../types';
const props=defineProps<{modelValue:Generation;targetId:string}>();
const emit=defineEmits<{'update:modelValue':[g:Generation]}>();
const store=useStudio(),summary=ref(''),available=ref('');
const drafts=new Map<string,string>();
const video=computed(()=>props.modelValue.mode.startsWith('h3'));
const modes=computed(()=>Object.entries(store.state?.catalog.modes || {}).filter(([mode])=>mode.startsWith('h3')===video.value));
const images=computed(()=>[...store.project.assets,...store.project.shots].filter(a=>a.imageFile));
async function modeChanged(mode:string,old:string){const g=props.modelValue;drafts.set(old,g.prompt);const saved=await store.defaults(props.targetId,mode);if(props.modelValue.mode!==mode)return;emit('update:modelValue',{...g,prompt:drafts.get(mode) ?? saved.prompt,references:g.references.length ? g.references : saved.references});}
watch(()=>props.modelValue.prompt,value=>drafts.set(props.modelValue.mode,value));
watch(()=>props.modelValue.mode,modeChanged);
let revision=0;
watch(()=>props.modelValue,async g=>{const serial=++revision;try{const s=await store.api<{width:number;height:number;frames:number;seconds:number}>('generation.preview',{generation:g});if(serial!==revision)return;summary.value=`输出 ${s.width} × ${s.height}`+(video.value?` · ${s.frames} 帧 / 24fps ≈ ${s.seconds.toFixed(2)} 秒`:'')}catch(e){summary.value=String(e)}},{deep:true,immediate:true});
function add(){if(available.value)props.modelValue.references.push(available.value)}
function move(i:number,n:number){const r=props.modelValue.references;const j=i+n;if(j<0||j>=r.length)return;const value=r.splice(i,1)[0]!;r.splice(j,0,value)}
async function importRefs(){const result=await store.api<string[]>('references.import');props.modelValue.references.push(...result)}
</script>
<template><div class="form-content"><label>工作流<select v-model="modelValue.mode" aria-label="生成工作流"><option v-for="[mode,name] in modes" :key="mode" :value="mode">{{name}}</option></select></label><label v-if="modelValue.mode!=='upscale'">提示词<textarea v-model="modelValue.prompt" rows="5" required aria-label="生成提示词"/></label><div v-if="modelValue.mode!=='upscale'" class="form-row"><label>画面比例<select v-model="modelValue.ratio"><option v-for="ratio in store.state?.catalog.ratios" :key="ratio">{{ratio}}</option></select></label><label>分辨率（MP）<input v-model.number="modelValue.megapixels" type="number" min=".1" max="16" step=".1" aria-label="分辨率 MP" required/></label></div><div class="form-row"><label>种子<input v-model="modelValue.seed" inputmode="numeric" pattern="[0-9]+" required aria-label="种子"/></label><label>采样步数 · 0 沿用工作流<input v-model.number="modelValue.steps" type="number" min="0" max="100" aria-label="采样步数" required/></label></div><label v-if="video">H3 时长（秒）<input v-model.number="modelValue.seconds" type="number" min=".2" max="149" step=".1" aria-label="H3 时长" required/></label><label v-if="video" class="checkbox-label"><input v-model="modelValue.cinema" type="checkbox"/>启用电影质感 LoRA</label><label v-if="video && modelValue.cinema">电影 LoRA 强度<input v-model.number="modelValue.cinema_strength" type="number" min="0" max="2" step=".1"/></label><label v-if="modelValue.mode==='quad'" class="checkbox-label"><input v-model="modelValue.quad_lora" type="checkbox"/>启用角色四视图 LoRA</label><label v-if="modelValue.mode.startsWith('qwen')" class="checkbox-label"><input v-model="modelValue.qwen_int8" type="checkbox"/>使用本机 INT8 模型</label><fieldset v-if="modelValue.mode==='krea'" class="lora-grid"><legend>Krea2 风格 LoRA · 分别启停</legend><label v-for="(trigger,name) in store.state?.catalog.styles" :key="name" class="checkbox-label" :title="trigger"><input v-model="modelValue.styles" type="checkbox" :value="name"/>{{name}}</label></fieldset><label v-if="modelValue.mode==='upscale'">高清放大倍数 · {{modelValue.scale}}×<input v-model.number="modelValue.scale" type="number" min="1" max="8" step=".1" aria-label="放大倍数" required/></label><section v-if="!['qwen','krea','h3_t2v'].includes(modelValue.mode)" class="reference-picker"><h3>参考图 · 按顺序引用</h3><div v-for="(file,i) in modelValue.references" :key="`${i}-${file}`" class="reference-row"><span>{{i+1}}. {{file}}</span><button type="button" class="icon-btn" aria-label="上移参考图" @click="move(i,-1)"><ArrowUp :size="13"/></button><button type="button" class="icon-btn" aria-label="下移参考图" @click="move(i,1)"><ArrowDown :size="13"/></button><button type="button" class="icon-btn" aria-label="移除参考图" @click="modelValue.references.splice(i,1)"><X :size="13"/></button></div><div class="form-row"><select v-model="available" aria-label="选择项目参考图"><option value="">选择项目素材…</option><option v-for="item in images" :key="item.id" :value="item.imageFile">{{item.name}}</option></select><button type="button" class="btn" @click="add"><Plus :size="14"/>加入参考</button></div><button type="button" class="btn" @click="importRefs">导入参考图片</button></section><p class="form-note">{{summary}}<br v-if="video"/><span v-if="video">修改时长后请核对提示词时间线；高规格请在本机实测显存。</span><span v-if="modelValue.mode==='qwen_edit'"> · 主参考图按此尺寸居中裁剪后编辑。</span></p></div></template>
